var a=69;var i=[{id:`cooking-069-01`,theoryId:69,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`A sauce tastes overly salty. Which approach truly lowers salt concentration?`,ua:`Соус надто солоний. Який спосіб реально зменшує концентрацію солі?`},explanation:{en:`Dilution reduces salt concentration; reducing the sauce concentrates it.`,ua:`Розбавлення знижує концентрацію солі, а уварювання підвищує її.`},options:[{id:`a`,text:{en:`Add unsalted base liquid or ingredients`,ua:`Додати несолону базову рідину або інгредієнти`}},{id:`b`,text:{en:`Boil the sauce longer`,ua:`Довше уварювати соус`}},{id:`c`,text:{en:`Add more soy sauce`,ua:`Додати більше соєвого соусу`}}],answer:{optionIds:[`a`]}},{id:`cooking-069-02`,theoryId:69,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`A squeeze of lemon can improve perceived balance without removing any dissolved salt.`,ua:`Крапля лимонного соку може покращити баланс смаку, не видаляючи розчинену сіль.`},explanation:{en:`Acid can alter perception, but the sodium remains.`,ua:`Кислота змінює сприйняття, але натрій залишається.`},answer:{value:!0}},{id:`cooking-069-03`,theoryId:69,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match a problem to a useful corrective strategy.`,ua:`Поєднайте проблему зі способом виправлення.`},explanation:{en:`Different flavor problems require different, measured responses.`,ua:`Різні смакові недоліки потребують різних і помірних виправлень.`},leftItems:[{id:`l1`,text:{en:`Overly salty`,ua:`Пересолено`}},{id:`l2`,text:{en:`Too sour`,ua:`Надто кисло`}},{id:`l3`,text:{en:`Too weak in aroma`,ua:`Бракує аромату`}}],rightItems:[{id:`r3`,text:{en:`Add a suitable fresh herb near service`,ua:`Додати відповідну свіжу зелень перед подачею`}},{id:`r2`,text:{en:`Rebalance using compatible sweetness or richness`,ua:`Збалансувати доречною солодкістю чи жирністю`}},{id:`r1`,text:{en:`Dilute with unsalted components`,ua:`Розбавити несолоними компонентами`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-069-04`,theoryId:69,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order a sensible seasoning adjustment cycle.`,ua:`Упорядкуйте розумний цикл коригування смаку.`},explanation:{en:`Incremental adjustments minimize overshooting.`,ua:`Поступові коригування зменшують ризик переборщити.`},steps:[{id:`s2`,text:{en:`Add a small measured adjustment`,ua:`Додати невелику відміряну поправку`}},{id:`s1`,text:{en:`Taste and identify the dominant imbalance`,ua:`Скуштувати й визначити головний дисбаланс`}},{id:`s3`,text:{en:`Mix, wait as needed, and taste again`,ua:`Перемішати, за потреби почекати й скуштувати знову`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-069-05`,theoryId:69,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which attempt to fix oversalted soup is counterproductive?`,ua:`Яка спроба виправити пересолений суп погіршить ситуацію?`},explanation:{en:`Evaporation retains salt while reducing liquid volume.`,ua:`При випаровуванні сіль залишається, а об’єм рідини зменшується.`},options:[{id:`a`,text:{en:`Add unsalted vegetables and liquid`,ua:`Додати несолоні овочі та рідину`}},{id:`b`,text:{en:`Prepare an unsalted second batch and combine`,ua:`Приготувати несолону другу порцію й змішати`}},{id:`c`,text:{en:`Reduce the soup until half the liquid evaporates`,ua:`Уварити суп, доки випарується половина рідини`}}],answer:{optionIds:[`c`]}},{id:`cooking-069-06`,theoryId:69,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A liter of soup contains 10 g salt. You add 1 liter of unsalted soup without losing liquid. How many grams of salt are now in each liter?`,ua:`Літр супу містить 10 г солі. Ви додаєте 1 л несолоного супу без втрати рідини. Скільки грамів солі тепер припадає на кожний літр?`},explanation:{en:`The total 10 g of salt is now distributed over 2 liters: 5 g per liter.`,ua:`Загальні 10 г солі розподілено на 2 літри: 5 г на літр.`},numericInput:{unit:`g`,unitLabel:{en:`grams`,ua:`грамів`},allowDecimals:!1},answer:{value:5,tolerance:0,unit:`g`}}];var n={theoryId:69,exercises:i};export{n as default,i as exercises,a as theoryId};